import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>كل تحويل صيغة يغيّر طريقة حفظ صورتك، وبعض هذه التغييرات تفقد بيانات لا تعود أبدًا. فهم فقدان الجودة يمنعك من إفساد صورك دون قصد.</p>\n<p>القاعدة سهلة القول وسهلة النسيان: الصيغ مع الفقدان تتخلص من التفاصيل، والصيغ دون فقدان تحفظ كل شيء. الاختيار بينهما يحدد مصير صورتك.</p>\n<p>يشرح هذا المقال فقدان الجودة بكلمات بسيطة. ستعرف ماذا يحدث داخل كل تحويل، مع <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a>.</p>\n<h2 id=\"what-quality-loss-means\">ماذا يعني فقدان الجودة فعلًا؟</h2>\n<p>فقدان الجودة يعني أن بيانات من الصورة حُذفت أثناء الحفظ ولا يمكن استعادتها. الصورة الناتجة تحمل معلومات أقل من الأصل.</p>\n<p>الفقدان ليس دائمًا سيئًا. إذا حُذفت بيانات لا تراها العين، فالصورة تبدو كما هي بحجم أصغر. المشكلة تبدأ عندما يُحذف ما يُرى.</p>\n<h2 id=\"lossy-vs-lossless\">مع الفقدان مقابل دون فقدان: الفرق الأساسي</h2>\n<p>مع الفقدان مقابل دون فقدان: الفرق الأساسي. الصيغ مع الفقدان مثل JPG تحذف بيانات لتقليص الحجم، والصيغ دون فقدان مثل PNG تحفظ كل بكسل بدقة.</p>\n<p>مع الفقدان أصغر حجمًا بكثير، ودون فقدان أكبر حجمًا لكن بجودة كاملة. الاختيار بينهما يعتمد على أولويتك: الحجم أم الكمال.</p>\n<h2 id=\"jpg-quality-explained\">جودة JPG مشروحة بصدق</h2>\n<p>جودة JPG مشروحة بصدق: منزلق الجودة من 0 إلى 100 يحدد مقدار البيانات المحذوفة. جودة 90 تحذف قليلًا، وجودة 50 تحذف كثيرًا.</p>\n<p>جودة 80 إلى 90 هي النقطة المثالية لمعظم الصور: حجم صغير وجودة ممتازة. أقل من 60 تبدأ العيوب في الظهور بوضوح.</p>\n<h2 id=\"png-lossless-truth\">PNG: دون فقدان، لكنه ليس سحرًا</h2>\n<p>PNG دون فقدان، لكنه ليس سحرًا. يحفظ كل بكسل بدقة، لكن ملفاته كبيرة جدًا للصور الفوتوغرافية. التحويل إلى PNG لا يضيف جودة لم تكن موجودة.</p>\n<p>إذا حوّلت JPG منخفض الجودة إلى PNG، فستحصل على ملف أكبر بالجودة السيئة نفسها. PNG يحفظ ما لديك، ولا يخترع ما فقدته.</p>\n<h2 id=\"webp-best-of-both\">WebP: هل هو الأفضل من العالمين؟</h2>\n<p>WebP: هل هو الأفضل من العالمين؟ يجمع بين ضغط قوي وجودة جيدة، وأصغر من JPG بالجودة نفسها. كما يدعم الشفافية مثل PNG.</p>\n<p>عيبه الوحيد التوافق: بعض البرامج القديمة والبوابات ترفضه. إذا قبلته منصتك، فهو خيار ممتاز لمعظم الصور.</p>\n<h2 id=\"heic-efficiency\">كفاءة HEIC وحدودها</h2>\n<p>كفاءة HEIC وحدودها: HEIC أصغر من JPG بجودة مماثلة، لذلك تستخدمه آيفون لتوفير المساحة. لكن دعمه محدود خارج أجهزة أبل.</p>\n<p>إذا شاركت صورك مع الآخرين أو رفعتها إلى بوابات، فحوّل HEIC إلى JPG أولًا. التوافق أهم من توفير بضعة كيلوبايتات.</p>\n<h2 id=\"lossy-to-lossless-myth\">خرافة التحويل من فقدان إلى دون فقدان</h2>\n<p>خرافة التحويل من فقدان إلى دون فقدان: لا يمكنك استعادة جودة فُقدت بتحويل الملف إلى PNG. البيانات المحذوفة ذهبت إلى الأبد.</p>\n<p>التحويل إلى PNG بعد فقدان الجودة يجعل الملف أكبر دون تحسين الصورة. إنه وهم شائع يكلفك مساحة دون فائدة.</p>\n<h2 id=\"repeated-conversions\">لماذا تضر التحويلات المتكررة؟</h2>\n<p>لماذا تضر التحويلات المتكررة؟ كل تحويل بصيغة مع الفقدان يحذف مزيدًا من البيانات. بعد ثلاث أو أربع جولات، تصبح الصورة باهتة ومشوهة.</p>\n<p>الحل بسيط: حوّل دائمًا من الملف الأصلي. احتفظ بالأصل، واصنع كل نسخة منه مباشرة، لا من نسخة محوّلة سابقًا.</p>\n<h2 id=\"quality-settings-that-work\">إعدادات الجودة التي تعمل فعلًا</h2>\n<p>إعدادات الجودة التي تعمل فعلًا: للصور الفوتوغرافية استخدم جودة 80 إلى 90. للصور الرئيسية استخدم 90، وللصور المصغرة يكفي 75.</p>\n<p>للنصوص والرسوم، استخدم PNG دون قلق بشأن الجودة. النص يحتاج حدة كاملة، وPNG يعطيها دون فقدان.</p>\n<h2 id=\"checking-visible-damage\">كيف تكشف الضرر المرئي؟</h2>\n<p>لكشف الضرر المرئي، كبّر الصورة وافحص المناطق الناعمة: السماء والوجوه والجدران. الضرر يظهر ككتل مربعة أو شرائط لون.</p>\n<p>قارن النتيجة بالأصل جنبًا إلى جنب. إذا لاحظت الفرق دون تكبير، فالجودة منخفضة جدًا ويجب إعادة التحويل.</p>\n<h2 id=\"when-conversion-is-safe\">متى يكون التحويل آمنًا تمامًا؟</h2>\n<p>التحويل آمن تمامًا عندما تحوّل من الأصل بجودة عالية إلى صيغة مناسبة. مثلًا، تحويل PNG إلى JPG بجودة 90 آمن في معظم الحالات.</p>\n<p>كما أن التحويل بين صيغ دون فقدان آمن دائمًا. PNG إلى WebP دون فقدان لا يضر بالصورة إطلاقًا.</p>\n<h2 id=\"when-to-keep-the-original\">متى تحتفظ بالأصل؟</h2>\n<p>احتفظ بالأصل عندما تكون الصورة مهمة أو قد تحتاج إلى تحويلات مستقبلية. الأصل هو مصدر كل نسخة، وفقدانه يعني فقدان الجودة إلى الأبد.</p>\n<p>للصور العادية اليومية، لا حاجة إلى الاحتفاظ بالأصل. لكن للصور المهنية والعائلية المهمة، احتفظ بالأصل دائمًا.</p>\n<h2 id=\"generation-problem\">مشكلة الأجيال بكلمات بسيطة</h2>\n<p>مشكلة الأجيال بكلمات بسيطة: كل جيل من التحويل يفقد جودة. الجيل الأول من الأصل ممتاز، والجيل الثاني جيد، والجيل الخامس سيئ.</p>\n<p>تجنب الأجيال المتعددة بالتحويل من الأصل دائمًا. جيل واحد من الأصل أفضل من خمسة أجيال متتالية.</p>\n<h2 id=\"lossy-formats-compared\">الصيغ مع الفقدان مقارنة بالكفاءة</h2>\n<p>الصيغ مع الفقدان مقارنة بالكفاءة: WebP الأكثر كفاءة، ثم HEIC، ثم JPG. WebP يعطي أصغر ملف بجودة معينة.</p>\n<p>لكن الكفاءة ليست كل شيء. التوافق والدعم يهمّان أيضًا، وJPG يتفوق فيهما رغم كفاءته الأقل.</p>\n<h2 id=\"screenshots-suffer-more\">لماذا تعاني لقطات الشاشة أكثر من الصور؟</h2>\n<p>لماذا تعاني لقطات الشاشة أكثر من الصور؟ لأنها تحمل نصًا وحوافًا حادة ومساحات مسطحة، وهي أصعب على الضغط مع الفقدان.</p>\n<p>النص الصغير يفقد حدته بسرعة عند التحويل بجودة منخفضة. للقطات الشاشة، استخدم جودة عالية أو صيغة PNG.</p>\n<h2 id=\"archiving-masters\">كيف تؤرشف النسخ الرئيسية للمستقبل؟</h2>\n<p>لأرشفة النسخ الرئيسية للمستقبل، احتفظ بالملفات الأصلية بصيغ دون فقدان أو بجودة عالية جدًا. الأرشيف هو مصدر كل نسخة مستقبلية.</p>\n<p>خزّن الأصول في مكان آمن مع نسخة احتياطية. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-tahwil-as-suwar/\">الدليل الكامل لمحول الصور</a> و<a href=\"/ar/blog/kayfiyya-tahwil-sighat-as-sura/\">كيفية تحويل صيغة صورة</a>. وللتحويل إلى WebP، جرّب <a href=\"/ar/\">محول JPG إلى WebP</a> أو ابدأ من <a href=\"/ar/tahwil-jpg-ila-webp/\">الصفحة الرئيسية</a> لاستكشاف كل الأدوات.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يفقد تحويل JPG إلى WebP الجودة؟","answer":"قد يفقد قليلًا من الجودة إذا استخدمت جودة منخفضة، لكن بجودة 85 أو أعلى يكون الفقدان غير ملحوظ تقريبًا. WebP يحافظ على التفاصيل أفضل من JPG بالحجم نفسه."},{"question":"هل من الأفضل التحويل إلى PNG أم WebP لموقع إلكتروني؟","answer":"لموقع إلكتروني، WebP أفضل لأنه أصغر بجودة مماثلة. PNG يناسب الرسوم والنصوص فقط. إذا لم تقبل منصتك WebP، فاستخدم JPG."},{"question":"هل يمكنني تحويل JPG منخفض الجودة إلى PNG عالي الجودة؟","answer":"لا، التحويل لا يضيف جودة. JPG منخفض الجودة فقد تفاصيل لا يمكن استعادتها، وتحويله إلى PNG يجعل الملف أكبر دون تحسين الصورة."},{"question":"كم مرة يمكنني تحويل صورة قبل أن تبدو سيئة؟","answer":"يعتمد على الجودة المستخدمة. التحويل بجودة عالية يمكن تكراره مرات عدة دون ضرر ملحوظ، لكن التحويل بجودة منخفضة يفسد الصورة بعد جولتين أو ثلاث."},{"question":"هل يؤثر تحويل صورة في ألوانها؟","answer":"قد يؤثر قليلًا. الصيغ المختلفة تعالج الألوان بطرق مختلفة، لكن الفرق عادة ضئيل. إذا كانت دقة اللون مهمة، فراجع النتيجة على شاشة جيدة."},{"question":"هل يجب أن أحوّل صوري إلى HEIC لتوفير المساحة؟","answer":"ليس بالضرورة. HEIC يوفّر مساحة على آيفون، لكن توافقه محدود خارج أجهزة أبل. إذا شاركت صورك مع الآخرين، فاحتفظ بـJPG."}];
